H.background();
const m = P.m, b = P.b;
const xint = Math.abs(m) > 1e-9 ? -b / m : NaN;
// Window includes the y-intercept (0,b) and the x-intercept (xint,0). Capped so
// a near-horizontal line doesn't shrink the picture to nothing; the line is
// drawn by fn so it stays visible regardless.
const span = Math.min(40, Math.max(8, (Number.isFinite(xint) ? Math.abs(xint) : 0) + 1.5, Math.abs(b) + 3));
const v = H.plot2d({ xMin: -span, xMax: span, yMin: -span, yMax: span });
v.grid(); v.axes();
v.fn(x => m * x + b, { color: H.colors.accent, width: 3 });
v.dot(0, b, { r: 7, fill: H.colors.good });
v.text("y-int (0, " + b.toFixed(1) + ")", span * 0.04, b + span * 0.08, { color: H.colors.good, size: 12 });
if (Number.isFinite(xint)) {
  // keep the marker on-screen even past the cap; label always shows true value
  const xMark = H.clamp(xint, -span + 0.5, span - 0.5);
  v.dot(xMark, 0, { r: 7, fill: H.colors.warn });
  v.text("x-int (" + xint.toFixed(1) + ", 0)", xMark + span * 0.04, -span * 0.09, { color: H.colors.warn, size: 12 });
}
// probe sweep bounded so the moving point's height stays inside the window
const xsAmp = Math.min(span - 2, Math.max(0.3, (span - Math.abs(b) - 1) / Math.max(Math.abs(m), 1e-6)));
const xs = xsAmp * Math.sin(t * 0.6);
v.dot(xs, m * xs + b, { r: 5, fill: H.colors.accent2 });
H.text("x- and y-intercepts", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("y-int: set x=0 -> y=" + b.toFixed(1) + "    x-int: set y=0 -> x=" + (Number.isFinite(xint) ? xint.toFixed(1) : "none (horizontal)"), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "y-intercept", color: H.colors.good }, { label: "x-intercept", color: H.colors.warn }], H.W - 180, 28);
